                && "JSON".equals(rt2.getFormat()) && "PROD".equals(rt2.getGroupName()),
                "roundtrip config 2 restored");
        check(configMapper.findByNamespaceId(ns4.getId()).size() == 2, "roundtrip exactly 2 configs");

